import java.io.*;
import java.util.*;

public class Main {
    static byte[] buf;
    static int pos;

    static String next() {
        while (buf[pos] <= ' ') pos++;
        int start = pos;
        while (pos < buf.length && buf[pos] > ' ') pos++;
        return new String(buf, start, pos - start);
    }

    static long nextLong() {
        while (buf[pos] <= ' ') pos++;
        boolean neg = buf[pos] == '-';
        if (neg) pos++;
        long r = 0;
        while (pos < buf.length && buf[pos] > ' ') r = r * 10 + (buf[pos++] - '0');
        return neg ? -r : r;
    }

    static int nextInt() {
        return (int) nextLong();
    }

    public static void main(String[] args) throws IOException {
        buf = System.in.readAllBytes();
        int n = nextInt();
        long budget = nextLong();
        long[][] orders = new long[n][2];
        for (int i = 0; i < n; i++) orders[i][0] = nextLong();
        for (int i = 0; i < n; i++) orders[i][1] = nextLong();
        // nearer first; at equal distance, cheaper first
        Arrays.sort(orders, (p, q) -> p[0] != q[0] ? Long.compare(p[0], q[0]) : Long.compare(p[1], q[1]));
        int answer = 0;
        for (long[] o : orders) {
            if (o[1] > budget) break;
            budget -= o[1];
            answer++;
        }
        System.out.println(answer);
    }
}

package main

import (
	"bufio"
	"fmt"
	"os"
	"sort"
	"strconv"
)

func main() {
	sc := bufio.NewScanner(os.Stdin)
	sc.Buffer(make([]byte, 1<<20), 1<<20)
	sc.Split(bufio.ScanWords)
	next := func() int {
		sc.Scan()
		v, _ := strconv.Atoi(sc.Text())
		return v
	}
	n, budget := next(), next()
	orders := make([][2]int, n)
	for i := range orders {
		orders[i][0] = next()
	}
	for i := range orders {
		orders[i][1] = next()
	}
	// nearer first; at equal distance, cheaper first
	sort.Slice(orders, func(p, q int) bool {
		if orders[p][0] != orders[q][0] {
			return orders[p][0] < orders[q][0]
		}
		return orders[p][1] < orders[q][1]
	})
	answer := 0
	for _, o := range orders {
		if o[1] > budget {
			break
		}
		budget -= o[1]
		answer++
	}
	fmt.Println(answer)
}
